ient::addMenuItem(%clientId, "2Don't Reset", "no"); return; } else if(%opt == "observe") { Observer::setTargetClient(%clientId, %cl); return; } else if(%opt == "insomniax") { Client::buildMenu(%clientId, "Insomniax Mod Settings:", "ixsettings", true); Client::addMenuItem(%clientId, "1Server: Anti-TK Lvl", "tkserv " @ $Insomniax::tkServerLvl); Client::addMenuItem(%clientId, "2Client: Anti-TK Lvl", "tkclient " @ $Insomniax::tkClientLvl); Client::addMenuItem(%clientId, "3Out of Bounds Kill", "areakill " @ $Insomniax::LeaveAreaTime); if($Insomniax::PSkin) Client::addMenuItem(%clientId, "4Disable Personal Skins", "disablepskin " @ %clientId); else Client::addMenuItem(%clientId, "4Enable Personal Skin", "enablepskin " @ %clientId); if($Insomniax::FairTeams) Client::addMenuItem(%clientId, "5Disable Fair Teams", "disableFT " @ %clientId); else Client::addMenuItem(%clientId, "5Enable Fair Teams", "enableFT " @ %clientId); if(%clientId.isSuperAdmin) Client::addMenuItem(%clientId, "6Admin Controls.", "admincontrols"); return; } else if(%opt == "additional") { %numnow = 0; Client::buildMenu(%clientId, "Additional Options:","additional", true); if($curVoteTopic == "") { %IXKiller = Insomniax_getKiller(%clientId); if((%IXKiller != %clientId) && ($tkKills[%IXKiller] >= $Insomniax::tkLimit)) { if($Insomniax::tkClientLvl == 1) Client::addMenuItem(%clientId, %numnow++ @ "Kick Team Killer " @ Client::getName(Insomniax_getKiller(%clientId)), "tkopt " @ getClientByName(Client::getName(%IXKiller))); else Client::addMenuItem(%clientId, %numnow++ @ "Vote to Kick " @ Client::getName(Insomniax_getKiller(%clientId)), "tkopt " @ getClientByName(Client::getName(%IXKiller))); } } if($insomniax::PSkin) if(%clientId.custom) Client::addMenuItem(%clientId, %numnow++ @ "Use Server Skins.", "pskin off"); else Client::addMenuItem(%clientId, %numnow++ @ "Use Personal Skins.", "pskin on"); if(Player::getMountedItem(Client::getOwnedObject(%clientId),$BackpackSlot) == "Vengeance") { Client::addMenuItem(%clientId, %numnow++ @ "Set Vengeance Payload.", "payload"); Client::addMenuItem(%clientId, %numnow++ @ "Set Vengeance Scan.", "scan"); Client::addMenuItem(%clientId, %numnow++ @ "Set Vengeance Warhead.", "warhead"); } return; } Game::menuRequest(%clientId); } function processMenuKAffirm(%clientId, %opt) { if(getWord(%opt, 0) == "yes") Admin::kick(%clientId, getWord(%opt, 1)); Game::menuRequest(%clientId); } function processMenuBAffirm(%clientId, %opt) { if(getWord(%opt, 0) == "yes") Admin::kick(%clientId, getWord(%opt, 1), true); Game::menuRequest(%clientId); } function processMenuAAffirm(%clientId, %opt) { if(getWord(%opt, 0) == "yes") { if(%clientId.isSuperAdmin) { %cl = getWord(%opt, 1); %cl.isAdmin = true; $ixAdmin[%cl] = true; messageAll(0, Client::getName(%clientId) @ " made " @ Client::getName(%cl) @ " into an admin."); } } Game::menuRequest(%clientId); } function processMenuRAffirm(%clientId, %opt) { if(%opt == "yes" && %clientId.isAdmin) { messageAll(0, Client::getName(%clientId) @ " reset the server to default settings."); Server::refreshData(); } Game::menuRequest(%clientId); } function processMenuCTLimit(%clientId, %opt) { remoteSetTimeLimit(%clientId, %opt); } function processMenuIXSettings(%clientId, %option) { %opt = getWord(%option, 0); %cl = getWord(%option, 1); if(%opt == "admincontrols") { Client::buildMenu(%clientId, "Admin Controls:", "ixsettings", true); if($Insomniax::PAVote) Client::addMenuItem(%clientId, "1Disable Admin Voting", "disablepav"); else Client::addMenuItem(%clientId, "1Enable Admin Voting", "enablepav"); Client::addMenuItem(%clientId, "2Admin Lockouts", "palockout"); Client::addMenuItem(%clientId, "3Voting Lockouts", "pvlockout"); Client::addMenuItem(%clientId, "4Purge Public Admins", "purge " @ %clientId); return; } else if(%opt == "disablepav") { Client::sendMessage(%clientId, 3, "Admin Voting is DISABLED"); $Insomniax::PAVote = "false"; } else if(%opt == "enablepav") { Client::sendMessage(%clientId, 3, "Admin Voting is ENABLED"); $Insomniax::PAVote = "true"; } else if(%opt == "disableFT") { Client::sendMessage(%clientId, 3, "Fair Teams Checking is DISABLED"); $Insomniax::fairteams = "false"; } else if(%opt == "enableFT") { Client::sendMessage(%clientId, 3, "Fair Teams Checking is ENABLED"); $Insomniax::fairteams = "true"; } else if(%opt == "tkserv") { Client::buildMenu(%clientId, "Current Server Anti-TK: " @ %cl, "ServerLvl", true); Client::addMenuItem(%clientId, "0Log TK's only", 0); Client::addMenuItem(%clientId, "1Auto Vote TKer", 1); Client::addMenuItem(%clientId, "2Auto Vote Until Kicked", 2); Client::addMenuItem(%clientId, "3Auto Kick TKer", 3); return; } else if(%opt == "tkclient") { Client::buildMenu(%clientId, "Current Client Anti-TK: " @ %cl, "ClientLvl", true); Client::addMenuItem(%clientId, "0Client Vote Option", 0); Client::addMenuItem(%clientId, "1Client Kick Option", 1); return; } else if(%opt == "areakill") { Client::buildMenu(%clientId, "Out of Bounds Kill Time: " @ %cl @ " Seconds", "AKill", true); Client::addMenuItem(%clientId, "0Set to Off", 0); Client::addMenuItem(%clientId, "1Set to 10 Seconds", 10); Client::addMenuItem(%clientId, "2Set to 15 Seconds", 15); Client::addMenuItem(%clientId, "3Set to 20 Seconds", 20); Client::addMenuItem(%clientId, "4Set to 25 Seconds", 25); Client::addMenuItem(%clientId, "5Set to 30 Seconds", 30); Client::addMenuItem(%clientId, "6Set to 40 Seconds", 40); Client::addMenuItem(%clientId, "7Set to 60 Seconds", 60); return; } else if(%opt == "palockout") { Client::buildMenu(%clientId, "Current Status:","PALockouts", true); Client::addMenuItem(%clientId, "1[" @ whattodo($Insomniax::PATeamChange) @ "]Team Changing", "teamchange " @ $Insomniax::PATeamChange); Client::addMenuItem(%clientId, "2[" @ whattodo($Insomniax::PAKick) @ "]Kick", "kick " @ $Insomniax::PAKick); Client::addMenuItem(%clientId, "3[" @ whattodo($Insomniax::PABan) @ "]Ban","ban " @ $Insomniax::PABan); Client::addMenuItem(%clientId, "4[" @ whattodo($Insomniax::PAMission) @ "]Change Mission", "mission " @ $Insomniax::PAMission); Client::addMenuItem(%clientId, "5[" @ whattodo($Insomniax::PATeamDamage) @ "]Team Damage", "teamdamage " @ $Insomniax::PATeamDamage); Client::addMenuItem(%clientId, "6[" @ whattodo($Insomniax::PATourneyMode) @ "]Tourney/FFA Mode", "tourney " @ $Insomniax::PATourneyMode); Client::addMenuItem(%clientId, "7[" @ whattodo($Insomniax::PATimeLimit) @ "]Time Limit", "timelimit " @ $Insomniax::PATimeLimit); Client::addMenuItem(%clientId, "8Additional Lockouts ...", "additional"); return; } else if(%opt == "pvlockout") { Client::buildMenu(%clientId, "Current Status:","PVLockouts", true); Client::addMenuItem(%clientId, "1[" @ whattodo($Insomniax::PVKick) @ "]Kick", "kick " @ $Insomniax::PVKick); Client::addMenuItem(%clientId, "2[" @ whattodo($Insomniax::PVMission) @ "]Change Mission", "mission " @ $Insomniax::PVMission); Client::addMenuItem(%clientId, "3[" @ whattodo($Insomniax::PVTeamDamage) @ "]Team Damage", "teamdamage " @ $Insomniax::PVTeamDamage); Client::addMenuItem(%clientId, "4[" @ whattodo($Insomniax::PVTourneyMode) @ "]Tourney/FFA Mode", "tourney " @ $Insomniax::PVTourneyMode); Client::addMenuItem(%clientId, "5[Unlock]ALL Options", "allon"); return; } else if(%opt == "purge") { Client::sendMessage(%cl,3,"Purging All Public Admins of Admin Status."); Insomniax_clearPA(%cl); Client::sendMessage(%cl,3,"Purging Complete."); return; } else if(%opt == "disablepskin") ixAllSkinsOff(); else if(%opt == "enablepskin") ixAllSkinsOn(); processMenuOptions(%clientId, "insomniax"); } function processMenuPALockouts(%clientId, %option) { %opt = getWord(%option, 0); %toggle = getWord(%option, 1); if(%opt == "additional") { Client::buildMenu(%clientId, "Current Status:","PALockouts", true); Client::addMenuItem(%clientId, "1[" @ whattodo($Insomniax::PAResetDefaults) @ "]Server Defaults ", "reset " @ $Insomniax::PAResetDefaults); Client::addMenuItem(%clientId, "2[" @ whattodo($Insomniax::PAModOptions) @ "]Insomniax Mod Options", "modopt " @ $Insomniax::PAModOptions); Client::addMenuItem(%clientId, "3[" @ whattodo($Insomniax::PATeamInfo) @ "]Set Team Info", "teaminfo " @ $Insomniax::PATeamInfo); Client::addMenuItem(%clientId, "4[Unlock]ALL Options", "allon"); return; } else if(%opt == "allon") { %access = "All Admin Options"; %toggle = "false"; $Insomniax::PATeamChange = "true"; $Insomniax::PAKick = "true"; $Insomniax::PABan = "true"; $Insomniax::PAMission = "true"; $Insomniax::PATeamInfo = "true"; $Insomniax::PATeamDamage = "true"; $Insomniax::PATourneyMode = "true"; $Insomniax::PATimeLimit = "true"; $Insomniax::PAResetDefaults = "true"; $Insomniax::PAModOptions = "true"; } else if(%opt == "teamchange") { %access = "Admin: Team Change"; if(%toggle) $Insomniax::PATeamChange = "false"; else $Insomniax::PATeamChange = "true"; } else if(%opt == "kick") { %access = "Admin: Kick"; if(%toggle) $Insomniax::PAKick = "false"; else $Insomniax::PAKick = "true"; } else if(%opt == "ban") { %access = "Admin: Ban"; if(%toggle) $Insomniax::PABan = "false"; else $Insomniax::PABan = "true"; } else if(%opt == "mission") { %access = "Admin: Change Mission"; if(%toggle) $Insomniax::PAMission = "false"; else $Insomniax::PAMission = "true"; } else if(%opt == "teamdamage") { %access = "Admin: Enable/Disable Team Damage"; if(%toggle) $Insomniax::PATeamDamage = "false"; else $Insomniax::PATeamDamage = "true"; } else if(%opt == "tourney") { %access = "Admin: Toggle Tourney/FFA Mode"; if(%toggle) $Insomniax::PATourneyMode = "false"; else $Insomniax::PATourneyMode = "true"; } else if(%opt == "timelimit") { %access = "Admin: Change Time Limit"; if(%toggle) $Insomniax::PATimeLimit = "false"; else $Insomniax::PATimeLimit = "true"; } else if(%opt == "reset") { %access = "Admin: Reset Sever"; if(%toggle) $Insomniax::PAResetDefaults = "false"; else $Insomniax::PAResetDefaults = "true"; } else if(%opt == "modopt") { %access = "Admin: Insomniax Mod Options"; if(%toggle) $Insomniax::PAModOptions = "false"; else $Insomniax::PAModOptions = "true"; } else if(%opt == "teaminfo") { %access = "Admin: Set Team Info"; if(%toggle) $Insomniax::PATeamInfo = "false"; else $Insomniax::PATeamInfo = "true"; } if(%toggle) %toggle = "false"; else %toggle = "true"; Client::sendMessage(%clientId, 3, "[" @ islocked(%toggle) @ "] " @ %access); ixecho(%clientId,"[" @ islocked(%toggle) @ "] " @ %access); Game::menuRequest(%clientId); } function processMenuPVLockouts(%clientId, %option) { %opt = getWord(%option, 0); %toggle = getWord(%option, 1); if(%opt == "kick") { %access = "Vote to Kick"; if(%toggle) $Insomniax::PVKick = "false"; else $Insomniax::PVKick = "true"; } else if(%opt == "mission") { %access = "Vote to Change Mission"; if(%toggle) $Insomniax::PVMission = "false"; else $Insomniax::PVMission = "true"; } else if(%opt == "teamdamage") { %access = "Vote to Enable/Disable Team Damage"; if(%toggle) $Insomniax::PVTeamDamage = "false"; else $Insomniax::PVTeamDamage = "true"; } else if(%opt == "tourney") { %access = "Vote to Change to Tourney/FFA Mode"; if(%toggle) $Insomniax::PVTourneyMode = "false"; else $Insomniax::PVTourneyMode = "true"; } else if(%opt == "allon") { %access = "All Vote Options"; %toggle = "false"; $Insomniax::PVKick = "true"; $Insomniax::PVMission = "true"; $Insomniax::PVTeamDamage = "true"; $Insomniax::PVTourneyMode = "true"; } if(%toggle) %toggle = "false"; else %toggle = "true"; Client::sendMessage(%clientId, 3, "[" @ islocked(%toggle) @ "] " @ %access); ixecho(%clientId,"[" @ islocked(%toggle) @ "] " @ %access); Game::menuRequest(%clientId); } function islocked(%toggle) { if(%toggle) return "Unlocked"; else return "-Locked-"; } function whattodo(%toggle) { if(%toggle) return "-Lock-"; else return "Unlock"; } function processMenuServerLvl(%clientId, %option) { $Insomniax::tkServerLvl = %option; if(%option == 0) messageAll(0, "SERVER:TK Protection Level Set to Zero. (Logging TK's only)."); if(%option == 1) messageAll(0, "SERVER:TK Protection Level Set to One. (Auto Vote)."); if(%option == 2) messageAll(0, "SERVER:TK Protection Level Set to Two. (Auto Vote Until Kicked)."); if(%option == 3) messageAll(0, "SERVER:TK Protection Level Set to Three. (Auto Kick)."); } function processMenuClientLvl(%clientId, %option) { $Insomniax::tkClientLvl = %option; if(%option == 0) messageAll(0, "SERVER: Client TK Vote Option Engaged. (From Options Menu)."); if(%option == 1) messageAll(0, "SERVER: Client TK Kick Option Engaged. (From Options Menu)."); } function processMenuAKill(%clientId, %option) { $Insomniax::LeaveAreaTime = %option; if(%option == 0) messageAll(0, "SERVER: Leaving Mission Area Now Does not Kill you."); else messageAll(0, "SERVER: Leaving Mission Area Now Kills you in " @ %option @ " Seconds."); } function processMenuAdditional(%clientId, %option) { %opt = getWord(%option, 0); %cl = getWord(%option, 1); if(%opt == "pskin") { if(%cl == "on") { %clientId.custom = true; bottomprint(%clientId,"<jc><f2>Custom Skins Enabled.\n<f1>Changes Take Place on Next Respawn", 5); } else { %clientId.custom = false; bottomprint(%clientId,"<jc><f2>Custom Skins Disabled.\n<f1>Changes Take Place on Next Respawn", 5); } } else if(%opt == "payload") { Client::buildMenu(%clientId, "Current Payload: " @ $ixVPayload[%clientId],"additional", true); Client::addMenuItem(%clientId, "1Fire 1 Projectile.", "number 1"); Client::addMenuItem(%clientId, "2Fire 2 Projectiles.", "number 2"); Client::addMenuItem(%clientId, "3Fire 3 Projectiles.", "number 3"); Client::addMenuItem(%clientId, "4Fire 4 Projectiles.", "number 4"); Client::addMenuItem(%clientId, "5Fire 5 Projectiles.", "number 5"); return; } else if(%opt == "number") { $ixVPayload[%clientId] = %cl; playSound(SoundChangePayload,GameBase::getPosition(Client::getOwnedObject(%clientId))); bottomprint(%clientId,"<jc><f2>Vengeance Payload Update.\n<f1>Now set to Launch " @ %cl @ " Warheads", 5); } else if(%opt == "scan") { Client::buildMenu(%clientId, "Current Scan: " @ $ixVScanner[%clientId],"additional", true); Client::addMenuItem(%clientId, "1Short/Wide Scan.", "scanner Short"); Client::addMenuItem(%clientId, "2Medium/Thin Scan.", "scanner Medium"); Client::addMenuItem(%clientId, "3Long/Tight Scan.", "scanner Long"); return; } else if(%opt == "scanner") { $ixVScanner[%clientId] = %cl; bottomprint(%clientId,"<jc><f2>Vengeance Scanner Update.\n<f1>Now Scanning " @ %cl @ " Range.", 5); } else if(%opt == "warhead") { Client::buildMenu(%clientId, "Ammo After Launch: ","additional", true); Client::addMenuItem(%clientId, "1Warhead #1: " @ $ixVWarhead[%clientId, 1], "loadout 1"); Client::addMenuItem(%clientId, "2Warhead #2: " @ $ixVWarhead[%clientId, 2], "loadout 2"); Client::addMenuItem(%clientId, "3Warhead #3: " @ $ixVWarhead[%clientId, 3], "loadout 3"); Client::addMenuItem(%clientId, "4Warhead #4: " @ $ixVWarhead[%clientId, 4], "loadout 4"); Client::addMenuItem(%clientId, "5Warhead #5: " @ $ixVWarhead[%clientId, 5], "loadout 5"); return; } else if(%opt == "loadout") { Client::buildMenu(%clientId, "Choose Load for Warhead: " @ %cl,"additional", true); Client::addMenuItem(%clientId, "1Low Yield: " @ $ixVAmmo[Low], "loadlow " @ %cl); Client::addMenuItem(%clientId, "2Medium Yield: " @ $ixVAmmo[Medium], "loadmed " @ %cl); Client::addMenuItem(%clientId, "3High Yield: " @ $ixVAmmo[High], "loadhigh " @ %cl); Client::addMenuItem(%clientId, "4EMP: " @ $ixVAmmo[EMP], "loademp " @ %cl); Client::addMenuItem(%clientId, "5Pause Sequence: 0", "loadpause " @ %cl); return; } else if(%opt == "loadlow") { $ixVWarhead[%clientId, %cl] = "Low"; bottomprint(%clientId,"<jc><f2>Vengeance Warhead Update.\n<f1>Warhead " @ %cl @ " is now Low Yield", 5); playSound(SoundLoadWarhead,GameBase::getPosition(Client::getOwnedObject(%clientId))); processMenuAdditional(%clientId, "warhead"); return; } else if(%opt == "loadmed") { $ixVWarhead[%clientId, %cl] = "Medium"; bottomprint(%clientId,"<jc><f2>Vengeance Warhead Update.\n<f1>Warhead " @ %cl @ " is now Medium Yield", 5); playSound(SoundLoadWarhead,GameBase::getPosition(Client::getOwnedObject(%clientId))); processMenuAdditional(%clientId, "warhead"); return; } else if(%opt == "loadhigh") { $ixVWarhead[%clientId, %cl] = "High"; bottomprint(%clientId,"<jc><f2>Vengeance Warhead Update.\n<f1>Warhead " @ %cl @ " is now High Yield", 5); playSound(SoundLoadWarhead,GameBase::getPosition(Client::getOwnedObject(%clientId))); processMenuAdditional(%clientId, "warhead"); return; } else if(%opt == "loademp") { $ixVWarhead[%clientId, %cl] = "EMP"; bottomprint(%clientId,"<jc><f2>Vengeance Warhead Update.\n<f1>Warhead " @ %cl @ " is holding an EMP Charge", 5); playSound(SoundLoadWarhead,GameBase::getPosition(Client::getOwnedObject(%clientId))); processMenuAdditional(%clientId, "warhead"); return; } else if(%opt == "loadpause") { $ixVWarhead[%clientId, %cl] = "Pause"; bottomprint(%clientId,"<jc><f2>Vengeance Warhead Update.\n<f1>Warhead " @ %cl @ " set to Pause the Sequence", 5); playSound(SoundLoadWarhead,GameBase::getPosition(Client::getOwnedObject(%clientId))); processMenuAdditional(%clientId, "warhead"); return; } else if(%opt == "tkopt") { if($Insomniax::tkClientLvl == 1) { Admin::Kick(-3, Insomniax_getKiller(%clientId)); return; } else { %cl.voteTarget = true; %clientId.selClient = Insomniax_getKiller(%clientId); Admin::startVote(%clientId, "Kick Team Killer " @ Client::getName(%cl), "tkkick", %cl); return; } } processMenuOptions(%clientId, "additional"); } function Insomniax_ServerLvlTxt() { if($Insomniax::tkServerLvl == 0) %tkText = "Only Logging TK's"; else if($Insomniax::tkServerLvl == 1) %tkText = "Votes at " @ $Insomniax::tkLimit @ " TK's"; else if($Insomniax::tkServerLvl == 2) %tkText = "Votes at " @ $Insomniax::tkLimit @ " TKs and Kicks at " @ $Insomniax::tkLimit * $Insomniax::tkMultiple @ " TK's"; else if($Insomniax::tkServerLvl == 3) %tkText = "Kicks at " @ $Insomniax::tkLimit @ " TK's"; else %tkText = "ERROR: Server Level set to Unkown Level"; return %tkText; } function Insomniax_ClientLvlTxt() { if($Insomniax::tkClientLvl == 0) %tkText = "Vote Option at " @ $Insomniax::tkLimit @ " TK's"; else if($Insomniax::tkClientLvl == 1) %tkText = "Kick Option at " @ $Insomniax::tkLimit @ "TK's"; else %tkText = "ERROR: Client Level set to Unkown Level"; return %tkText; } function Insomniax_setTeamKill(%victimId, %killerId) { $tkVictim[%killerId] = %victimId; $tkKiller[%victimId] = %killerId; $tkKills[%killerId] += 1; echo("IX-Admin: TK Recorded. victimId: ",%victimId," killerId: ",%killerId," Killer now has ",$tkKills[%killerId]," TKs"); %trigger = $tkKills[%killerId] % $Insomniax::tkLimit; %tkTopKills = $Insomniax::tkLimit * $Insomniax::tkMultiple; if(($tkKills[%killerId] >= $Insomniax::tkLimit) && (!%trigger)) { if($Insomniax::tkServerLvl) { if($Insomniax::tkServerLvl != 3) { if(($tkKills[%killerId] >= %tkTopKills) && ($Insomniax::tkServerLvl != 1)) { messageAll(0, Client::getName(%killerId) @ " has been kicked for Team Killing. Confirmed " @ $tkKills[%killerId] @ " Team Kills."); Admin::Kick(-2, %killerId); return; } %killerId.voteTarget = true; %victimId.selClient = Insomniax_getKiller(%victimId); Admin::startVote(%victimId, "Kick Team Killer " @ Client::getName(%killerId), "tkkick", %killerId); } else { messageAll(0, Client::getName(%killerId) @ " has been kicked for Team Killing. Confirmed " @ $tkKills[%killerId] @ " Team Kills."); Admin::Kick(-2, %killerId); } } } return; } function Insomniax_clearPA(%admin) { if(%admin.isSuperAdmin) { ixecho(%admin,"Purge All Public Admins"); %numPlayers = getNumClients(); for(%i = 0; %i < %numPlayers; %i++) { %pl = getClientByIndex(%i); if(!%pl.isSuperAdmin && %pl.isAdmin) { %pl.isAdmin = false; $ixAdmin[%client] = false; Client::sendMessage(%pl,1,"Your Admin Status has been revoked by the Super Admin."); Client::sendMessage(%admin,3,"Public Admin Status Stripped from: " @ Client::getName(%pl) @ "."); ixecho(%admin,"Stripped Admin from " @ Client::getName(%pl)); } } } } function Insomniax_getKiller(%clientId) { return $tkKiller[%clientId]; } function Insomniax_getVictim(%client