Your Admin Status was revoked by the Super Admin."); echo("IX-Admin: Removed Admin: ",Client::getName(%pl)); } } echo("IX-Admin: Purging Complete."); echo("IX-Admin: ",%j," Admins Purged."); echo("IX-Admin: -=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-"); } function ixSave() { echo("IX-Admin: -=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-"); echo("IX-Admin: Saving Insomniax Mod Settings for ",$InsomniaxInternalVersion); export("Insomniax::*", "config\\insomniax.cs", False); export("DefaultTeamEnergy", "config\\insomniax.cs", True); echo("IX-Admin: Settings Saved."); echo("IX-Admin: -=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-"); } exec(ixUserList); function IxAdmin_Authenticate(%clientId, %ip) { if($UserList::Activated) { %user = ixGetUser(%ip); %currentName = Client::getName(%clientId); if(%user) { %username = getWord($UserList::User[%user], 1); %flags = getWord($UserList::User[%user], 3); $ixUserInfo[%clientId] = $UserList::User[%user]; if(%username != %currentName) { echo("IX-Admin: User: ",%username," Identified as ",%currentName,". Access Level: ",%flags); ixAdminMsg("User: " @ %username @ " Identified as " @ %currentName @ ". Access Level: " @ %flags); } else { echo("IX-Admin: User: ",%username," Identified. Access Level: ",%flags); ixAdminMsg("User: " @ %username @ " Identified. Access Level: " @ %flags); } if(%flags == "AutoSuper") { %clientId.isAdmin = true; %clientId.isSuperAdmin = true; $ixAdmin[%clientId] = true; $ixSuperAdmin[%clientId] = true; ixAdminMsg(%username @ " Automaticly Logged in."); } else if(%flags == "AutoPublic") { %clientId.isAdmin = true; $ixAdmin[%clientId] = true; ixAdminMsg(%username @ " Automaticly Logged in."); } } else { echo("IX-Admin: User: ",%currentName," Unknown."); $ixUserInfo[%clientId] = "0 " @ %currentName @ " None None " @ %ip; } } } function ixProcess(%client, %name, %user, %username, %flags, %password) { if(!%client.isAdmin) { %realpass = getWord($UserList::User[%user], 2); if(!String::ICompare(%password, %realpass)) { if((%flags == "PublicAdmin") && (%name == %username)) { %client.isAdmin = true; $ixAdmin[%client] = true; } if((%flags == "SuperAdmin") && (%name == %username)) { %client.isAdmin = true; %client.isSuperAdmin = true; $ixAdmin[%client] = true; $ixSuperAdmin[%client] = true; } ixAdminMsg(%username @ " Logged in."); } else { Client::sendMessage(%client, 0,"IX-Server: Bad Password"); ixAdminMsg(%name @ " Login attempt Failed. Username: " @ %username); } } else { Client::sendMessage(%client, 0,"IX-Server: You Already have Admin Status."); } } function ixAdminMsg(%msg) { %numPlayers = getNumClients(); for(%i = 0; %i < %numPlayers; %i++) { %pl = getClientByIndex(%i); if($ixAdmin[%pl]) { Client::sendMessage(%pl, 0, "IX-Server: " @ %msg); } } } function ixGetUser(%check) { for(%i=1;%i <= $UserList::MaxUsers;%i++) { for(%j=4;((%mask = getWord($UserList::User[%i], %j)) != -1);%j++) { if(ixCompareIP(%check,%mask)) return %i; } } return 0; } function ixPrepIP(%transport) { %x = 0; %i = 0; %now = 0; while((%x<2)&&(%i < 30)) { if(String::getSubStr(%transport,%i,1) == ":") { if(!%now) %now = %i+1; else return String::getSubStr(%transport, %now, %i - %now); %x++; } %i++; } return "172.16.0.0"; } function TestPrep() { echo(ixPrepIP("IP:172.16.0.0:1089")); } function ixCompareIP(%ip, %mask) { %ipNow = ixDotToSpace(%ip); %maskNow = ixDotToSpace(%mask); for(%x=0;%x<4;%x++) { %one = getWord(%ipNow, %x); %two = getWord(%maskNow, %x); if((%one != %two) && (%two != "*")) return "false"; } return "true"; } function ixStrLen(%string) { for(%i=0; String::getSubStr(%string, %i, 1) != "";%i++) %length = %i; %length++; return %length; } function ixDotToSpace(%string) { %x = 0; %i = 0; while(%x<3) { %char = String::getSubStr(%string,%i,1); if(!String::ICompare(%char, ".")) { %left = String::getSubStr(%string,0,%i); %right = String::getSubStr(%string,%i+1,(ixStrLen(%string)-%i)); %string = strcat(%left," ",%right); %x++; } %i++; } return %string; } function Insom